import React from 'react';

import clsx from 'clsx';

import styles from './styles.module.less';

const StatYearGlass: React.FC<React.HtmlHTMLAttributes<HTMLDivElement>> = ({
  children,
  ...rest
}) => (
  <div {...rest} className={clsx(rest.className, styles.glass)}>
    {children}
  </div>
);

export default StatYearGlass;
