import React, { useState } from 'react';

import clsx from 'clsx';
import { toBlob } from 'html-to-image';
import { Link } from 'react-router-dom';

import ObstacleAva from '@apps/Obstacles/components/ObstacleAva';
import ObstacleCategoryBadge from '@apps/Obstacles/components/ObstacleCategoryBadge/ObstacleCategoryBadge';
import { getOneFriendData } from '@apps/Users/@services/user.services';
import { IOneFriend } from '@apps/Users/@types/user.types';
import Logo from '@components/Logo';
import PageLoader from '@components/PageLoader';
import { saveBlob } from '@helpers/files.helper';
import { declOfNum, formatAltitude } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohIcon from '@ui-kit/Icon';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohLink from '@ui-kit/Link';
import PohList from '@ui-kit/List';

import { IStatYearTotal } from './statYear.types';
import StatYearGlass from './StatYearGlass';
import StatYearMap from './StatYearMap';
import StatYearProductItem from './StatYearProductItem';
import StatYearWidget from './StatYearWidget';
import styles from './styles.module.less';
import { AuthContext } from '../../../contexts/AuthContext';
import { getUrlFromObstacleType } from '../../Obstacles/@mappers/obstacles.url.mapper';
import { getObstacleTypeName } from '../../Obstacles/@resources/obstacles.resource';
import { ObstacleCategory, ObstacleType } from '../../Obstacles/@types/obstacles.types';
import { getUserFoodStatisticByYear, getUserStatisticByYear } from '../@services/user.service';
import { IUserFoodStatisticDTO, IUserYearStatisticDTO } from '../@types/user.types';

function StatYear({ user, year }: { user?: number; year?: number }) {
  const [data, setData] = useState<IUserYearStatisticDTO[] | null>(null);
  const [veryOldData, setVeryOldData] = useState<IUserYearStatisticDTO[]>([]);
  const [oldData, setOldData] = useState<IUserYearStatisticDTO[]>([]);
  const [userData, setUserData] = useState<IOneFriend | null>(null);
  const [loading, setLoading] = useState(false);
  const [food, setFood] = useState<IUserFoodStatisticDTO[]>([]);
  const [more, setMore] = useState(5);
  const [error, setError] = useState<string | null>(null);

  const ref = React.useRef<HTMLDivElement>(null);
  const authContext = React.useContext(AuthContext);

  const id_user = user ?? authContext.user?.id ?? 0;
  const currentYear = year ?? new Date().getFullYear();

  React.useEffect(() => {
    const start = async () => {
      try {
        setLoading(true);
        const friendResult = await getOneFriendData(id_user);
        if (!friendResult.statistic && friendResult.id !== authContext.user?.id) {
          throw new Error(
            'К сожалению вы не были в походе с человеком, страницу которого пытаетесь посмотреть',
          );
        }
        setUserData(friendResult);

        const statForYearResultCurrent = await getUserStatisticByYear(id_user, currentYear);
        setData(statForYearResultCurrent);

        const foodRes = await getUserFoodStatisticByYear(id_user, currentYear);
        setFood(foodRes);

        getUserStatisticByYear(id_user, currentYear - 1).then(setOldData);
        getUserStatisticByYear(id_user, currentYear - 2).then(setVeryOldData);
      } catch (err) {
        setError((err as Error).message);
      } finally {
        setLoading(false);
      }
    };

    start();
  }, [user, year]);

  if (error) {
    return (
      <PohRow>
        <PohCol sm={{ span: 8, offset: 2 }} className={'p-5 text-center'}>
          <p className="display-1">🧐</p>
          <p className="text-center h2">{error}</p>
          <p className="text-center h5">Не отчаивайтесь! Всё впереди!</p>
        </PohCol>
      </PohRow>
    );
  }
  if (!data || !userData || loading) {
    return <PageLoader />;
  }

  const total: IStatYearTotal = {
    distance: 0,
    alt_ascent: 0,
    alt_descent: 0,
    alt_max: -Infinity,
    alt_min: Infinity,
    duration: 0,
    productsCount: round(food.reduce((s, a) => s + +a.amount * 1, 0) / 1000, 1),
    tracks: [],
    hiking: [],
  };

  const totalOld: IStatYearTotal = {
    distance: 0,
    alt_ascent: 0,
    alt_descent: 0,
    alt_max: -Infinity,
    alt_min: Infinity,
    duration: 0,
    tracks: [],
    hiking: [],
    productsCount: 0,
  };

  const totalVeryOld: IStatYearTotal = {
    distance: 0,
    alt_ascent: 0,
    alt_descent: 0,
    alt_max: -Infinity,
    alt_min: Infinity,
    duration: 0,
    tracks: [],
    hiking: [],
    productsCount: 0,
  };

  type Mms = { id: string; name: string; surname: string; photo: string; count: number };
  type AggregatedObstaclesStat = {
    id: string;
    name: string;
    type: string;
    category: string;
    altitude: string;
    count: number;
  };

  const obstacles: Record<string, AggregatedObstaclesStat> = {};
  const members: Record<string, Mms> = {};
  const membersOld: Record<string, Mms> = {};
  const membersVeryOld: Record<string, Mms> = {};

  const aggregation = data.reduce<Record<string, IStatYearTotal>>((acc, val) => {
    if (!acc[val.type_name]) {
      acc[val.type_name] = {
        distance: 0,
        alt_ascent: 0,
        alt_descent: 0,
        alt_max: -Infinity,
        alt_min: Infinity,
        duration: 0,
        hiking: [],
        tracks: [],
        productsCount: 0,
      };
    }

    acc[val.type_name].distance += +val.distance;
    acc[val.type_name].alt_ascent += +val.alt_ascent;
    acc[val.type_name].alt_descent += +val.alt_descent;
    acc[val.type_name].alt_max = Math.max(+acc[val.type_name].alt_max, +val.alt_max);
    acc[val.type_name].duration +=
      new Date(val.date_finish).getTime() - new Date(val.date_start).getTime();
    if (+val.alt_min != 0) {
      acc[val.type_name].alt_min = Math.min(+acc[val.type_name].alt_min, +val.alt_min);
      total.alt_min = Math.min(+total.alt_min, +val.alt_min);
    }

    val.friends.split('\n').forEach((f) => {
      const [id, name, surname, photo] = f.split('→');

      if (!members[id]) {
        members[id] = { id, name, surname, photo, count: 0 };
      }
      members[id].count++;
    });

    val.obstacles?.split('\n').forEach((f) => {
      const [id, name, type, category, altitude, _id_hiking_obstacle, _date_in, _date_out] =
        f.split('→');

      if (!obstacles[id]) {
        obstacles[id] = { id, name, type, category, altitude, count: 0 };
      }
      obstacles[id].count++;
    });

    acc[val.type_name].hiking.push({
      id: +val.id,
      name: val.name,
      ava: val.ava,

      start: new Date(val.date_start),
      finish: new Date(val.date_finish),
    });

    val.tracks.split('\n').forEach((f) => {
      const [id, trackdata, distance, date_start, date_finish] = f.split('→');

      if (trackdata) {
        acc[val.type_name].tracks.push({ id, trackdata, distance, date_start, date_finish });
        total.tracks.push({ id, trackdata, distance, date_start, date_finish });
      }
    });

    total.distance += +val.distance;
    total.alt_ascent += +val.alt_ascent;
    total.alt_descent += +val.alt_descent;
    total.alt_max = Math.max(+total.alt_max, +val.alt_max);
    total.duration += new Date(val.date_finish).getTime() - new Date(val.date_start).getTime();
    return acc;
  }, {});

  // oldAggregation
  oldData.reduce<Record<string, IStatYearTotal>>((acc, val) => {
    if (!acc[val.type_name]) {
      acc[val.type_name] = {
        distance: 0,
        alt_ascent: 0,
        alt_descent: 0,
        alt_max: -Infinity,
        alt_min: Infinity,
        duration: 0,
        productsCount: 0,
        hiking: [],
        tracks: [],
      };
    }

    acc[val.type_name].distance += +val.distance;
    acc[val.type_name].alt_ascent += +val.alt_ascent;
    acc[val.type_name].alt_descent += +val.alt_descent;
    acc[val.type_name].alt_max = Math.max(+acc[val.type_name].alt_max, +val.alt_max);
    acc[val.type_name].duration +=
      new Date(val.date_finish).getTime() - new Date(val.date_start).getTime();
    if (+val.alt_min != 0) {
      acc[val.type_name].alt_min = Math.min(+acc[val.type_name].alt_min, +val.alt_min);
      totalOld.alt_min = Math.min(+total.alt_min, +val.alt_min);
    }

    val.friends.split('\n').forEach((f) => {
      const [id, name, surname, photo] = f.split('→');

      if (!membersOld[id]) {
        membersOld[id] = { id, name, surname, photo, count: 0 };
      }
      membersOld[id].count++;
    });

    acc[val.type_name].hiking.push({
      id: +val.id,
      name: val.name,
      ava: val.ava,

      start: new Date(val.date_start),
      finish: new Date(val.date_finish),
    });

    val.tracks.split('\n').forEach((f) => {
      const [id, trackdata, distance, date_start, date_finish] = f.split('→');

      if (trackdata) {
        acc[val.type_name].tracks.push({ id, trackdata, distance, date_start, date_finish });
        totalOld.tracks.push({ id, trackdata, distance, date_start, date_finish });
      }
    });

    totalOld.distance += +val.distance;
    totalOld.alt_ascent += +val.alt_ascent;
    totalOld.alt_descent += +val.alt_descent;
    totalOld.alt_max = Math.max(+totalOld.alt_max, +val.alt_max);
    totalOld.duration += new Date(val.date_finish).getTime() - new Date(val.date_start).getTime();
    return acc;
  }, {});

  // veryOldAggregation
  veryOldData.reduce<Record<string, IStatYearTotal>>((acc, val) => {
    if (!acc[val.type_name]) {
      acc[val.type_name] = {
        distance: 0,
        alt_ascent: 0,
        alt_descent: 0,
        alt_max: -Infinity,
        alt_min: Infinity,
        duration: 0,
        hiking: [],
        tracks: [],
        productsCount: 0,
      };
    }

    acc[val.type_name].distance += +val.distance;
    acc[val.type_name].alt_ascent += +val.alt_ascent;
    acc[val.type_name].alt_descent += +val.alt_descent;
    acc[val.type_name].alt_max = Math.max(+acc[val.type_name].alt_max, +val.alt_max);
    acc[val.type_name].duration +=
      new Date(val.date_finish).getTime() - new Date(val.date_start).getTime();
    if (+val.alt_min != 0) {
      acc[val.type_name].alt_min = Math.min(+acc[val.type_name].alt_min, +val.alt_min);
      totalVeryOld.alt_min = Math.min(+total.alt_min, +val.alt_min);
    }

    val.friends.split('\n').forEach((f) => {
      const [id, name, surname, photo] = f.split('→');

      if (!membersVeryOld[id]) {
        membersVeryOld[id] = { id, name, surname, photo, count: 0 };
      }
      membersVeryOld[id].count++;
    });

    acc[val.type_name].hiking.push({
      id: +val.id,
      name: val.name,
      ava: val.ava,
      start: new Date(val.date_start),
      finish: new Date(val.date_finish),
    });

    val.tracks.split('\n').forEach((f) => {
      const [id, trackdata, distance, date_start, date_finish] = f.split('→');

      if (trackdata) {
        acc[val.type_name].tracks.push({ id, trackdata, distance, date_start, date_finish });
        totalVeryOld.tracks.push({ id, trackdata, distance, date_start, date_finish });
      }
    });

    totalVeryOld.distance += +val.distance;
    totalVeryOld.alt_ascent += +val.alt_ascent;
    totalVeryOld.alt_descent += +val.alt_descent;
    totalVeryOld.alt_max = Math.max(+totalVeryOld.alt_max, +val.alt_max);
    totalVeryOld.duration +=
      new Date(val.date_finish).getTime() - new Date(val.date_start).getTime();
    return acc;
  }, {});

  type Agg = {
    name: string;
    count: number;
    amount: number;
    usages: IUserFoodStatisticDTO['usages'];
  };
  const aggregateFoodByRecipes = food.reduce<Record<string, Agg>>((acc, product) => {
    product.usages.forEach((u) => {
      if (!['Первое', 'Второе', 'Каши'].includes(u.category)) {
        return;
      }
      if (!acc[u.name]) {
        acc[u.name] = {
          name: u.name,
          count: 0,
          amount: 0,
          usages: [],
        };
      }

      if (!acc[u.name].usages.find((x) => x.date === u.date && x.act === u.act)) {
        acc[u.name].count++;
        acc[u.name].amount += parseFloat(u.amount) || 0;
        acc[u.name].usages.push(u);
      }
    });

    return acc;
  }, {});

  const compare = function <T>(fieldName: keyof T) {
    return (a: T, b: T) => {
      if (a[fieldName] < b[fieldName]) {
        return 1;
      }
      if (a[fieldName] > b[fieldName]) {
        return -1;
      }
      return 0;
    };
  };

  const handleShare = (prefDownload = false) => {
    ref.current &&
      toBlob(ref.current)
        .then(async (dataUrl) => {
          if (!dataUrl) return;
          const files = [
            new File([dataUrl], [userData.name, userData.surname, year].join('_') + '.png', {
              type: dataUrl.type,
            }),
          ];
          if (navigator.canShare({ files }) && !prefDownload) {
            try {
              await navigator.share({
                files,
                title: `Походный ${year}-й`,
                text: [userData.name, userData.surname, year].join(' '),
              });
            } catch (eee) {
              alert(`Error: ${(eee as Error).message}`);
            }
          } else {
            saveBlob(dataUrl, [userData.name, userData.surname, year].join('_') + '.png');
          }
        })
        .catch(function (eee) {
          console.error('oops, something went wrong!', eee);
        });
  };

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/users', text: 'Походники' },
          { href: `/user/${userData.id}`, text: [userData.name, userData.surname].join(' ') },
          { href: `/user/${userData.id}/stat/${year}`, text: `Статитстика ${year}`, active: true },
        ]}
      />

      <article>
        <div className={clsx(styles.header)} ref={ref}>
          <StatYearMap
            style={{ position: 'absolute', width: '100%', height: '720px', left: 0, top: 0 }}
            tracks={total.tracks}
            noControls
          />
          <div className={styles.cardsContainer}>
            <StatYearGlass className="p-3 d-flex flex-column align-items-center">
              <div className="lead">Итоги походного сезона</div>
              <h1 className={clsx('display-4 m-0', styles.accent)} style={{ color: '#fe4542' }}>
                {year}
              </h1>
              <Logo />
            </StatYearGlass>
            <StatYearGlass className="text-center p-3">
              <PohAva
                className="pull-left"
                width={100}
                src={userData.photo}
                alt={[userData.name, userData.surname].join(' ')}
              />
              <h5 className="mb-3">
                {userData.name}
                <br />
                {userData.surname}
              </h5>
            </StatYearGlass>
            <StatYearGlass className="text-center p-3">
              {' '}
              <StatYearWidget isAccent total={total} />
            </StatYearGlass>
          </div>
        </div>

        {navigator.canShare() ? (
          <div className="mt-1">
            <PohButton
              variant={ButtonVariant.Light}
              size={ButtonSize.Small}
              onClick={() => handleShare()}
            >
              <PohIcon name={IconsEnum.open}></PohIcon>&nbsp; Поделиться картинкой
            </PohButton>
          </div>
        ) : (
          <div className="mt-1">
            <PohButton
              variant={ButtonVariant.Light}
              size={ButtonSize.Small}
              onClick={() => handleShare(true)}
            >
              <PohIcon name={IconsEnum.download}></PohIcon>&nbsp; Скачать картинкой
            </PohButton>
          </div>
        )}

        <h2 className="page-header  pb-2 mb-4 mt-5">
          Походы{' '}
          <sup>
            <PohBadge rounded variant={BadgeVariant.Warning}>
              {data.length}
            </PohBadge>
          </sup>
        </h2>

        {Object.entries(aggregation).map(([typeName, typeData], i) => {
          return (
            <PohRow className="mt-5 mb-4 pb-4" key={i}>
              <PohCol sm={{ span: 4 }}>
                <h4>
                  {typeName}
                  <sup>
                    <PohBadge rounded variant={BadgeVariant.Warning}>
                      {typeData.hiking.length}
                    </PohBadge>
                  </sup>
                </h4>
                <StatYearWidget total={typeData} />

                <h6 className="mt-4">Походы</h6>
                <PohList
                  className="mb-3"
                  data={typeData.hiking.map(({ id, name, ava }) => ({
                    key: id,
                    title: name,
                    className: 'd-flex align-items-center p-0 pe-2 text-truncate flex-fill',
                    content: (
                      <>
                        <PohAva src={ava} alt={name} title={name} className="m-2" />
                        <b className="text-truncate" style={{ minWidth: 0 }}>
                          {name}
                        </b>
                      </>
                    ),
                    as: Link,
                    to: `/hiking/${id}`,
                    target: '_blank',
                    action: true,
                  }))}
                />
              </PohCol>
              <PohCol sm={{ span: 8 }}>
                <StatYearMap tracks={typeData.tracks} style={{ height: 320 }} />
              </PohCol>
            </PohRow>
          );
        })}

        <PohRow>
          <PohCol></PohCol>
        </PohRow>

        <PohRow className="my-4">
          <PohCol>
            <h4 className="mb-0">
              Люди с которыми вы были в походах{' '}
              <sup>
                <PohBadge rounded variant={BadgeVariant.Light}>
                  {Object.values(members).length - 1}
                </PohBadge>
              </sup>
            </h4>
            <small className="d-block mb-2">Кликнув можно посмотреть их статистику</small>
            <div className="text-start d-flex align-items-center justify-content-center text-truncate flex-wrap ">
              {Object.values(members)
                .filter((m) => +m.id !== userData.id)
                .sort(compare('count'))
                .map((m) => (
                  <PohLink
                    href={`/user/${m.id}/stat/${year}`}
                    target={'_blank'}
                    key={m.id}
                    className="position-relative p-2 m-1 d-block"
                  >
                    <PohAva
                      width={50}
                      src={m.photo}
                      alt={[m.name, m.surname].join(' ')}
                      title={[m.name, m.surname].join(' ')}
                    />
                    <PohBadge
                      rounded
                      variant={BadgeVariant.Light}
                      className="position-absolute"
                      style={{ top: 0, right: 0 }}
                    >
                      {m.count}
                    </PohBadge>
                  </PohLink>
                ))}
            </div>
          </PohCol>
        </PohRow>
        {Object.values(obstacles).length > 0 && (
          <PohRow className="my-4">
            <PohCol>
              <h4 className="mb-0">
                Пройденные препятствия и POI{' '}
                <sup>
                  <PohBadge rounded variant={BadgeVariant.Light}>
                    {Object.values(obstacles).length}
                  </PohBadge>
                </sup>
              </h4>
              <small className="d-block mb-2">Кликнув можно посмотреть подробнее</small>
              <div className="text-start d-flex align-items-center justify-content-center text-truncate flex-wrap ">
                {Object.values(obstacles)
                  .sort(compare('count'))
                  .map((m) => (
                    <PohLink
                      href={`/obstacles/${getUrlFromObstacleType(m.type as ObstacleType)}/${m.id}`}
                      target={'_blank'}
                      key={m.id}
                      className="position-relative p-2 m-1 d-block"
                    >
                      <div className={'d-flex align-items-center'} style={{ gap: 8 }}>
                        <div className="position-relative">
                          <ObstacleAva type={m.type as ObstacleType} />
                          <PohBadge
                            rounded
                            variant={BadgeVariant.Light}
                            className="position-absolute"
                            style={{ bottom: 0, right: 0 }}
                          >
                            {m.count}
                          </PohBadge>
                        </div>
                        <div style={{ lineHeight: 0.9 }}>
                          <small
                            className="d-block text-muted d-flex align-items-center"
                            style={{ gap: 8 }}
                          >
                            {getObstacleTypeName(m.type as ObstacleType)}
                            <span
                              className="d-block text-muted d-flex align-items-center"
                              style={{ gap: 5 }}
                            >
                              {formatAltitude(+m.altitude)}
                              &nbsp;
                              <ObstacleCategoryBadge category={m.category as ObstacleCategory} />
                            </span>
                          </small>
                          {m.name}
                        </div>
                      </div>
                    </PohLink>
                  ))}
              </div>
            </PohCol>
          </PohRow>
        )}
        {food.length > 0 && (
          <PohRow className="my-4">
            <PohCol>
              <h4 className="mb-0">
                Еда
                <sup>
                  <PohBadge rounded variant={BadgeVariant.Light}>
                    {total.productsCount}&thinsp;кг.
                  </PohBadge>
                </sup>
              </h4>
              <small className="d-block mb-2">Топы того что вы ели в походе</small>
              <PohRow>
                <PohCol sm={4}>
                  <h5>Топ блюда по количеству</h5>
                  <PohList
                    className="mb-2"
                    data={Object.values(aggregateFoodByRecipes)
                      .sort(compare('count'))
                      .slice(0, more)
                      .map((x) => ({
                        key: x.name,
                        content: (
                          <StatYearProductItem
                            count={x.count + '\u2008' + declOfNum(x.count, ['раз', 'раза', 'раз'])}
                          >
                            {x.name}
                          </StatYearProductItem>
                        ),
                        title: x.usages
                          .map((y) => `${new Date(y.date).toLocaleDateString()}\t${y.act}`)
                          .join('\n'),
                      }))}
                  />
                </PohCol>
                <PohCol sm={4}>
                  <h5>Топ блюда по массе</h5>
                  <PohList
                    className="mb-2"
                    data={Object.values(aggregateFoodByRecipes)
                      .sort(compare('amount'))
                      .slice(0, more)
                      .map((x) => ({
                        key: x.name,
                        content: (
                          <StatYearProductItem count={`${x.amount}г.`}>
                            {x.name}
                          </StatYearProductItem>
                        ),
                        title: x.usages
                          .map(
                            (y) =>
                              `${new Date(y.date).toLocaleDateString()}\t${round(+y.amount, 0)}\t${y.act}`,
                          )
                          .join('\n'),
                      }))}
                  />
                </PohCol>
                <PohCol sm={4}>
                  <h5>Топ продукты по массе</h5>
                  <PohList
                    className="mb-2"
                    data={food.slice(0, more).map((x) => ({
                      key: x.name,
                      content: (
                        <StatYearProductItem count={round(+x.amount, 0) + 'г.'}>
                          {x.name}
                        </StatYearProductItem>
                      ),
                      title: x.usages
                        .map(
                          (y) =>
                            `${new Date(y.date).toLocaleDateString()}\t${round(+y.amount, 0)}\t${y.act}`,
                        )
                        .join('\n'),
                    }))}
                  />
                </PohCol>
              </PohRow>
              <PohButton
                block
                variant={ButtonVariant.Light}
                className="my-1"
                onClick={() => setMore((m) => m + 5)}
              >
                Еще
              </PohButton>
            </PohCol>
          </PohRow>
        )}

        <PohRow>
          <PohCol>
            <h4>В сравнении с прошлыми годами</h4>
          </PohCol>
        </PohRow>
        <PohRow>
          {totalVeryOld.distance > 0 && (
            <PohCol sm={4}>
              <h4 className="text-center">
                <Link to={`/user/${user}/stat/${currentYear - 2}`}>{currentYear - 2}</Link>
              </h4>
              <StatYearWidget total={totalVeryOld} />
            </PohCol>
          )}
          {totalOld.distance > 0 && (
            <PohCol sm={4}>
              <h4 className="text-center">
                <Link to={`/user/${user}/stat/${currentYear - 1}`}>{currentYear - 1}</Link>
              </h4>
              <StatYearWidget total={totalOld} />
            </PohCol>
          )}
          <PohCol sm={4}>
            <h4 className="text-center">{year}</h4>
            <StatYearWidget total={total} />
          </PohCol>
        </PohRow>

        <PohRow>
          <PohCol className="text-center my-5 py-5">
            <h1 className="display-6">
              {userData.id === authContext.user?.id ? 'Ты' : userData.name}{' '}
              {userData.isGirl ? 'умница' : 'молодец'} :)
            </h1>
          </PohCol>
        </PohRow>
      </article>
    </PohContainer>
  );
}

export default StatYear;
