import React from 'react';

import { declOfNum, formatDistance } from '@helpers/formatHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { IStatYearTotal } from './statYear.types';
interface IStatYearWidgetProps {
  total: IStatYearTotal;
  isAccent?: boolean;
}

const StatYearWidget: React.FC<IStatYearWidgetProps> = ({ total, isAccent }) => {
  return (
    <div
      style={{ fontWeight: isAccent ? 'bold' : 'normal', fontSize: isAccent ? '1.1em' : 'normal' }}
    >
      <PohRow>
        <PohCol xs={{ span: 6 }} className="text-muted text-end text-nowrap">
          Преодолено:
        </PohCol>
        <PohCol xs={{ span: 6 }} className="text-danger text-nowrap text-start">
          {formatDistance(total.distance)}
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol xs={{ span: 6 }} className="text-muted text-end text-nowrap">
          Набрано:
        </PohCol>
        <PohCol
          xs={{ span: 6 }}
          className="text-nowrap text-start"
          title={`Это как подняться на ${Math.round(total.alt_ascent / 2.7)} ${declOfNum(Math.round(total.alt_ascent / 2.7), ['этаж', 'этажа', 'этажей'])}`}
        >
          {formatDistance(total.alt_ascent)}
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol xs={{ span: 6 }} className="text-muted text-end text-nowrap">
          Сброшено:
        </PohCol>
        <PohCol xs={{ span: 6 }} className="text-nowrap text-start">
          {formatDistance(total.alt_descent)}
        </PohCol>
      </PohRow>

      <PohRow>
        <PohCol xs={{ span: 6 }} className="text-muted text-end text-nowrap">
          Макс. высота:
        </PohCol>
        <PohCol xs={{ span: 6 }} className="text-nowrap text-start">
          {Number.isFinite(total.alt_max) && Math.abs(total.alt_max) > 0
            ? `${formatDistance(total.alt_max)}.н.у.м`
            : '-'}
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol xs={{ span: 6 }} className="text-muted text-end text-nowrap">
          Мин. высота:
        </PohCol>
        <PohCol xs={{ span: 6 }} className="text-nowrap text-start">
          {Number.isFinite(total.alt_min) && Math.abs(total.alt_min) > 0
            ? `${formatDistance(total.alt_min)}.н.у.м`
            : '-'}
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol xs={{ span: 6 }} className="text-muted text-end text-nowrap">
          Продолж.:
        </PohCol>
        <PohCol xs={{ span: 6 }} className="text-nowrap text-start">
          {(total.duration / 1000 / 60 / 60 / 24).toFixed(2)} дн.
        </PohCol>
      </PohRow>
      {total.productsCount > 0 && (
        <PohRow>
          <PohCol xs={{ span: 6 }} className="text-muted text-end text-nowrap">
            Съедено:
          </PohCol>
          <PohCol xs={{ span: 6 }} className="text-nowrap text-start">
            {total.productsCount} кг. еды
          </PohCol>
        </PohRow>
      )}
    </div>
  );
};

export default StatYearWidget;
