import React from 'react';

import clsx from 'clsx';

import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';

interface IStatYearProductItemProps extends React.HTMLAttributes<HTMLDivElement> {
  count: string;
}

const StatYearProductItem: React.FC<IStatYearProductItemProps> = ({ count, children, ...rest }) => (
  <div
    {...rest}
    className={clsx('d-flex align-items-center justify-content-between', rest.className)}
  >
    <div className="text-truncate">{children}</div>
    <PohBadge variant={BadgeVariant.Light}>{count}</PohBadge>
  </div>
);

export default StatYearProductItem;
